# eprintln!("{var:#?}");

assert_eq!(var.tag, *b"wght");
assert_eq!(var.name.as_deref(), Some("Weight"));
assert!((var.min_value - 100.0).abs() < f32::EPSILON);
assert!((var.default_value - 400.0).abs() < f32::EPSILON);
assert!((var.max_value - 800.0).abs() < f32::EPSILON);
assert!(!var.hidden);
# Ok(()) }
```

